package org.tkhjopf.app;

import org.tkhjopf.io.TimeSeriesIO;import org.tkhjopf.miner.*;import java.nio.file.*;import java.io.*;import java.util.*;
public final class BenchmarkRunner{
 public static void main(String[]args)throws Exception{if(args.length!=1)throw new IllegalArgumentException("usage: BenchmarkRunner config.properties");Properties p=new Properties();try(var in=Files.newInputStream(Path.of(args[0]))){p.load(in);}String[]ds=p.getProperty("datasets").split(","),modes=p.getProperty("modes","baseline,hj,hjtopk,tk,tk-no-pdub,tk-no-dub,tk-no-bounds").split(",");int warm=Integer.parseInt(p.getProperty("warmups","3")),rep=Integer.parseInt(p.getProperty("repeats","10"));double k=Double.parseDouble(p.getProperty("forgetting","0.1")),min=Double.parseDouble(p.getProperty("minsup","1.5"));int K=Integer.parseInt(p.getProperty("topk","5")),minLen=Integer.parseInt(p.getProperty("minlen","2")),max=Integer.parseInt(p.getProperty("maxlen","0"));Path out=Path.of(p.getProperty("output","results/benchmark.csv"));if(out.getParent()!=null)Files.createDirectories(out.getParent());try(PrintWriter w=new PrintWriter(Files.newBufferedWriter(out))){w.println("dataset,mode,run,n,k,minsup,topk,minlen,maxlen,runtime_ms,patterns,pair_attempts,compatible_pairs,pair_desc_prunes,branch_prunes,aligned_checks,peak_heap_mb");for(String d0:ds){Path d=Path.of(d0.trim());if(!d.isAbsolute())d=Path.of(args[0]).toAbsolutePath().getParent().getParent().resolve(d).normalize();double[]t=TimeSeriesIO.read(d);for(String mode0:modes){String mode=mode0.trim();for(int r=-warm;r<rep;r++){MiningResult x=run(mode,t,k,min,K,minLen,max);if(r>=0){var z=x.metrics();w.printf(Locale.ROOT,"%s,%s,%d,%d,%.12g,%.12g,%d,%d,%d,%.6f,%d,%d,%d,%d,%d,%d,%.3f%n",d.getFileName(),mode,r,t.length,k,min,K,minLen,max,z.runtimeNanos/1e6,x.patterns().size(),z.pairAttempts,z.compatiblePairs,z.pairDescendantPrunes,z.branchBoundPrunes,z.alignedOccurrenceChecks,z.approxPeakHeapBytes/1048576.0);w.flush();}}}}}System.out.println("Wrote "+out);}
 private static MiningResult run(String m,double[]t,double k,double min,int K,int minLen,int max){return switch(m){case"baseline"->new BaselineOPFMiner().mine(t,k,min,max);case"hj"->new HJOPFMiner().mine(t,k,min,max);case"hjtopk"->new ExhaustiveHJTopKMiner().mine(t,k,K,minLen,max);case"tk"->new TKHJOPFMiner().mine(t,k,K,minLen,max,true,true);case"tk-no-pdub"->new TKHJOPFMiner().mine(t,k,K,minLen,max,false,true);case"tk-no-dub"->new TKHJOPFMiner().mine(t,k,K,minLen,max,true,false);case"tk-no-bounds"->new TKHJOPFMiner().mine(t,k,K,minLen,max,false,false);default->throw new IllegalArgumentException(m);};}
}
